const startRaw = $input.first().json.startDate;
const endRaw = $input.first().json.endDate;

const pad2 = (n) => String(n).padStart(2, '0');

function parseDateTime(str) {
  // 兼容 2026-5-4、2026/5/4、2026-5-4 9:5:3、2026-05-04 09:05:03 等
  const m = String(str).trim().match(
    /^(\d{4})[-/](\d{1,2})[-/](\d{1,2})(?:[ T](\d{1,2}):(\d{1,2})(?::(\d{1,2}))?)?/
  );

  if (!m) {
    throw new Error(`无法解析日期时间: ${str}`);
  }

  const year = Number(m[1]);
  const month = Number(m[2]);
  const day = Number(m[3]);
  const hour = m[4] !== undefined ? Number(m[4]) : 0;
  const minute = m[5] !== undefined ? Number(m[5]) : 0;
  const second = m[6] !== undefined ? Number(m[6]) : 0;

  const dateStr = `${year}-${pad2(month)}-${pad2(day)}`;
  const dateTimeStr = `${dateStr} ${pad2(hour)}:${pad2(minute)}:${pad2(second)}`;

  return {
    year,
    month,
    day,
    hour,
    minute,
    second,
    dateStr,
    dateTimeStr
  };
}

const start = parseDateTime(startRaw);
const end = parseDateTime(endRaw);

// 使用 UTC 日期，避免时区导致日期错乱
let current = new Date(Date.UTC(start.year, start.month - 1, start.day));
const endDate = new Date(Date.UTC(end.year, end.month - 1, end.day));

const dateItems = [];

while (current <= endDate) {
  const currentDayStr = [
    current.getUTCFullYear(),
    pad2(current.getUTCMonth() + 1),
    pad2(current.getUTCDate())
  ].join('-');

  let dayStart;
  if (currentDayStr === start.dateStr) {
    // 第一天：使用传入的开始时间，统一补零格式化
    dayStart = start.dateTimeStr;
  } else {
    dayStart = `${currentDayStr} 00:00:00`;
  }

  let dayEnd;
  if (currentDayStr === end.dateStr) {
    // 最后一天：使用传入的结束时间，统一补零格式化
    dayEnd = end.dateTimeStr;
  } else {
    dayEnd = `${currentDayStr} 23:59:59`;
  }

  dateItems.push({
    json: {
      api_start_time: dayStart,
      api_end_time: dayEnd
    }
  });

  current.setUTCDate(current.getUTCDate() + 1);
}

return dateItems;

