// 1. 动态获取表头字段名（假设上游是「列出字段」节点）
const standardFields = $input.first().json.items.map(item => item.field_name);

// 2. 获取飞书返回的记录数组
const inputItems = $('查询商品配置表').first().json.items;

// 3. 【核心】拍平函数：把飞书各种复杂格式统一转成干净的值
function flattenValue(value) {
  if (value === null || value === undefined) return null;          // 空字段 → null
  if (typeof value !== 'object') return value;                     // 已是字符串/数字/布尔 → 直接返回
  if (Array.isArray(value)) {
    // 多行文本[{text}]、人员[{name}]、关联[{text}]等数组结构 → 提取并拼接
    return value.map(v => {
      if (v === null || v === undefined) return '';
      if (typeof v === 'object') return v.text ?? v.name ?? '';
      return String(v);
    }).join('');
  }
  // 单个富文本对象 → 取 text
  return value.text ?? value.name ?? '';
}

// 4. 遍历每条记录，构建扁平化对象
const outputItems = [];

for (const item of inputItems) {
  const fields = item.fields || {};

  const newObj = {
    record_id: item.record_id
  };

  for (const fieldName of standardFields) {
    // 【关键改动】：不再直接赋值原始值，而是经过 flattenValue 拍平
    newObj[fieldName] = flattenValue(fields[fieldName]);
  }

  outputItems.push({ json: newObj });
}

return outputItems;
